10	import MemoContent from "../MemoContent";
11	import { MemoViewContext, type MemoViewContextValue } from "../MemoView/MemoViewContext";
12	
13	interface MemoPreviewProps {
14	  content: string;
15	  attachments: Attachment[];
16	  name?: string;
17	  compact?: boolean;
18	  className?: string;
19	  creator?: User;
20	  showCreator?: boolean;
21	  showMemoId?: boolean;
22	  truncate?: boolean;
23	}
24	
25	const STUB_CONTEXT: MemoViewContextValue = {
26	  memo: create(MemoSchema),
27	  creator: undefined,
28	  currentUser: undefined,
29	  parentPage: "/",
30	  cardWidth: 0,
31	  isArchived: false,
32	  readonly: true,
33	  showBlurredContent: false,
34	  blurred: false,
35	  openEditor: () => {},
36	  toggleBlurVisibility: () => {},
37	  openPreview: () => {},
38	};
39	
40	const AttachmentThumbnails = ({ attachments }: { attachments: Attachment[] }) => {
41	  const visualAttachments = attachments.filter(
42	    (attachment) =>
43	      getAttachmentType(attachment) === "image/*" || getAttachmentType(attachment) === "video/*" || isMotionAttachment(attachment),
44	  );
45	  const items = buildAttachmentVisualItems(visualAttachments);
46	  const images = items.filter((item) => item.kind === "image" || item.kind === "motion");
47	  const others = items.filter((item) => item.kind === "video");
48	
49	  return (
50	    <div className="flex items-center gap-1.5 flex-wrap">
51	      {images.map((item) => (
52	        <div key={item.id} className="relative">
53	          <img
54	            src={item.posterUrl}
55	            alt={item.filename}
56	            className="w-10 h-10 rounded border border-border object-cover bg-muted/40"
57	            loading="lazy"
58	          />
59	          {item.kind === "motion" && (
60	            <span className="absolute left-1 top-1 rounded bg-black/70 px-1 py-0.5 text-[8px] font-semibold leading-none text-white">
61	              LIVE
62	            </span>
63	          )}
64	        </div>
65	      ))}
66	      {others.map((item) => (
67	        <div key={item.id} className="flex items-center gap-1 text-[10px] text-muted-foreground">
68	          <FileIcon className="w-3 h-3 shrink-0" />
69	          <span className="truncate max-w-[80px]">{item.filename}</span>
70	        </div>
71	      ))}
72	    </div>
73	  );
74	};
75	
76	const PreviewMeta = ({
77	  creator,
78	  showCreator,
79	  memoName,
80	  showMemoId,
81	}: {
82	  creator?: User;
83	  showCreator?: boolean;
84	  memoName?: string;
85	  showMemoId?: boolean;
86	}) => {
87	  const creatorName = creator?.displayName || creator?.username;
88	  const memoId = showMemoId && memoName ? extractMemoIdFromName(memoName).slice(0, 6) : undefined;
89	
90	  if (!creatorName && !memoId) {
91	    return null;
92	  }
93	
94	  return (
95	    <div className="flex items-center gap-1.5 text-xs text-muted-foreground leading-none shrink-0">
96	      {showMemoId && memoId && (
97	        <span className="text-[8px] font-mono px-1 py-0.5 rounded border border-border bg-muted/40 shrink-0">{memoId}</span>
98	      )}
99	      {showCreator && creatorName && <span className="font-medium text-foreground/80 truncate">{creatorName}</span>}
100	    </div>
101	  );
102	};
103	
104	const MemoPreview = ({
105	  content,
106	  attachments,
107	  name,
108	  compact = true,
109	  className,
110	  creator,
111	  showCreator = false,
112	  showMemoId = false,
113	  truncate = false,
114	}: MemoPreviewProps) => {
115	  const hasContent = content.trim().length > 0;
116	  const hasAttachments = attachments.length > 0;
117	  const showMeta = showCreator || showMemoId;
118	
119	  if (!hasContent && !hasAttachments) {
120	    return null;
121	  }
122	
123	  const meta = <PreviewMeta creator={creator} showCreator={showCreator} memoName={name} showMemoId={showMemoId} />;
124	  const contentNode = truncate ? (
125	    hasContent ? (
126	      <div className="text-sm text-muted-foreground truncate min-w-0">{content}</div>
127	    ) : hasAttachments ? null : (
128	      <div className="text-sm text-muted-foreground truncate min-w-0">No content</div>
129	    )
130	  ) : (
131	    // Previews are inert (pointer-events-none), so a static CSS bound replaces the
132	    // interactive clamp a full memo card gets.
133	    hasContent && (
134	      <div className="max-h-36 w-full overflow-hidden">
135	        <MemoContent content={content} compact={compact} />
136	      </div>
137	    )
138	  );
139	
140	  return (
141	    <MemoViewContext.Provider value={STUB_CONTEXT}>
142	      <div
143	        className={cn(
144	          "pointer-events-none",
145	          truncate ? "flex items-center gap-1.5 min-w-0 leading-tight" : "flex flex-col gap-1",
146	          className,
147	        )}
148	      >
149	        {showMeta && meta}
150	        {showMeta && truncate && (hasContent || hasAttachments) && <div className="text-muted-foreground/50 shrink-0">·</div>}
151	        {contentNode}
152	        {hasAttachments &&
153	          (truncate ? (
154	            <div className="shrink-0 text-muted-foreground/70 inline-flex justify-center items-center gap-0.5">
155	              <FileIcon className="w-3 h-3 inline-block" />
156	              <span className="text-xs">{countLogicalAttachmentItems(attachments)}</span>
157	            </div>
158	          ) : (
159	            <AttachmentThumbnails attachments={attachments} />
160	          ))}
161	      </div>
162	    </MemoViewContext.Provider>
163	  );
164	};
165	
166	export default MemoPreview;
